package credentials

import (
	"errors"
	"fmt"
	"sync/atomic"
	"testing"

	"github.com/zalando/go-keyring"
)

// hostStoreUnderTestMessage is the panic text of refuseUnderTest. It names what
// to do, because the person reading it is a developer whose test just reached
// the real secret store of the machine (DEVDESK-610).
const hostStoreUnderTestMessage = "credentials: a test reached the host secret store (%s) " +
	"without isolation; call fakekeyring.Install() in TestMain or fakekeyring.Fresh(t) " +
	"(DEVDESK-610, docs/architecture/configuration.md)"

// HostStore is the host secret manager as KeyringStorage and KeyringAvailable
// see it. The contract on a missing entry:
//   - Get returns an error for which errors.Is(err, ErrNotFound). go-keyring's
//     own ErrNotFound is not recognized here; goKeyring maps it.
//   - Delete returns nil.
//
// An implementation that returns any other error for a missing entry is seen as
// a real failure of the store: KeyringAvailable reports it unreachable.
type HostStore interface {
	Get(service, account string) (string, error)
	Set(service, account, secret string) error
	Delete(service, account string) error
}

// hostBox lets an atomic.Pointer hold an interface value, so a Cmd reading the
// current store while a t.Cleanup restores the previous one is not a data race.
type hostBox struct{ store HostStore }

var currentStore atomic.Pointer[hostBox]

// hostReachableUnderTest is set only by the TestMain of this package, whose
// tests mock go-keyring themselves and run git against a hermetic config. In
// any other test binary it stays false, so the real store is refused.
var hostReachableUnderTest atomic.Bool

// currentHost returns the store in use: goKeyring{} unless a test swapped it.
func currentHost() HostStore {
	if b := currentStore.Load(); b != nil {
		return b.store
	}
	return goKeyring{}
}

// SwapHostStoreForTest installs s and returns the store it replaces. It panics
// outside a test binary and when s is nil. Only _test.go files and
// internal/testutil/fakekeyring may call it.
func SwapHostStoreForTest(s HostStore) HostStore {
	if !testing.Testing() {
		panic("credentials: SwapHostStoreForTest called outside a test binary")
	}
	if s == nil {
		panic("credentials: SwapHostStoreForTest called with a nil HostStore; pass the store to restore, as returned by the previous call")
	}
	prev := currentHost()
	currentStore.Store(&hostBox{store: s})
	return prev
}

// refuseUnderTest panics with hostStoreUnderTestMessage when the code runs in a
// test binary that has not allowed the real host store. It panics rather than
// returning an error: an error would make Select fall back to memory and the
// test would pass, leaving the guard silent. op names the operation reached.
func refuseUnderTest(op string) {
	if testing.Testing() && !hostReachableUnderTest.Load() {
		panic(fmt.Sprintf(hostStoreUnderTestMessage, op))
	}
}

// goKeyring is the production HostStore and the only place go-keyring is
// called. Every method runs the test guard first.
type goKeyring struct{}

func (goKeyring) Get(service, account string) (string, error) {
	refuseUnderTest("keyring get")
	secret, err := keyring.Get(service, account)
	if errors.Is(err, keyring.ErrNotFound) {
		return "", fmt.Errorf("%w: %v", ErrNotFound, err)
	}
	return secret, err
}

func (goKeyring) Set(service, account, secret string) error {
	refuseUnderTest("keyring set")
	return keyring.Set(service, account, secret)
}

func (goKeyring) Delete(service, account string) error {
	refuseUnderTest("keyring delete")
	err := keyring.Delete(service, account)
	if errors.Is(err, keyring.ErrNotFound) {
		return nil
	}
	return err
}
package credentials

import (
	"os"
	"testing"

	"github.com/zalando/go-keyring"
)

// TestMain is the only place that allows the host-store guard to stand down
// (DEVDESK-610). The tests of this package either mock go-keyring themselves or
// run git against a hermetic config (hermeticGit), so none of them can reach
// the real Secret Service. The mock installed here is a net for a test that
// forgets to install its own.
func TestMain(m *testing.M) {
	keyring.MockInit()
	hostReachableUnderTest.Store(true)
	os.Exit(m.Run())
}
package fakekeyring

import (
	"fmt"
	"maps"
	"strconv"
	"sync"
	"testing"

	"github.com/anthnel/devdesk/internal/credentials"
)

// Store is an in-memory credentials.HostStore, safe for concurrent use. A store
// built by NewUnreachableStore fails every operation instead of holding entries.
type Store struct {
	mu      sync.Mutex
	entries map[string]string
	err     error // returned by every operation when set
}

// NewStore returns an empty, reachable store.
func NewStore() *Store {
	return &Store{entries: map[string]string{}}
}

// NewUnreachableStore returns a store whose Get, Set and Delete all return err
// as given: a locked keyring, no session bus. err is never wrapped in
// credentials.ErrNotFound, so KeyringAvailable sees the store as unreachable.
func NewUnreachableStore(err error) *Store {
	s := NewStore()
	s.err = err
	return s
}

// entryKey joins service and account without ambiguity: quoting escapes any
// separator-looking byte, so two different pairs never share a key.
func entryKey(service, account string) string {
	return strconv.Quote(service) + " " + strconv.Quote(account)
}

// Get returns the secret, or an error for which errors.Is(err,
// credentials.ErrNotFound) when there is none.
func (s *Store) Get(service, account string) (string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.err != nil {
		return "", s.err
	}
	secret, ok := s.entries[entryKey(service, account)]
	if !ok {
		return "", fmt.Errorf("fakekeyring: %w", credentials.ErrNotFound)
	}
	return secret, nil
}

// Set stores secret, replacing any previous one.
func (s *Store) Set(service, account, secret string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.err != nil {
		return s.err
	}
	s.entries[entryKey(service, account)] = secret
	return nil
}

// Delete removes the entry. A missing entry is not an error, as in the
// production adapter.
func (s *Store) Delete(service, account string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.err != nil {
		return s.err
	}
	delete(s.entries, entryKey(service, account))
	return nil
}

// Entries returns a copy of what the store holds, keyed by an opaque string.
func (s *Store) Entries() map[string]string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return maps.Clone(s.entries)
}

// Install puts a new empty store in use for the whole test binary and returns
// it. It is never restored: call it from TestMain.
func Install() *Store {
	s := NewStore()
	credentials.SwapHostStoreForTest(s)
	return s
}

// Fresh puts a new empty store in use for the test and restores the previous
// one at cleanup, so nested calls unwind in order.
func Fresh(t testing.TB) *Store {
	t.Helper()
	return use(t, NewStore())
}

// FreshUnreachable is Fresh with a store that fails every operation with err.
func FreshUnreachable(t testing.TB, err error) *Store {
	t.Helper()
	return use(t, NewUnreachableStore(err))
}

func use(t testing.TB, s *Store) *Store {
	t.Helper()
	prev := credentials.SwapHostStoreForTest(s)
	t.Cleanup(func() { credentials.SwapHostStoreForTest(prev) })
	return s
}
// Package fakekeyring is a fake of the host secret manager for tests
// (DEVDESK-610). It implements credentials.HostStore in memory, so a test never
// reaches the real Secret Service, Keychain or Credential Manager of the machine
// that runs it.
//
// It imports testing and is meant to be imported from _test.go files only, so
// it never reaches the production binary (a guard for that is to come, rule K3).
//
// Call Install in the TestMain of a package whose tests reach
// credentials.Select, KeyringStorage or KeyringAvailable, and Fresh(t) in each
// test that stores or reads a secret, so tests share no state.
// FreshUnreachable(t, err) stands for a locked or absent keyring.
