186	// starts from an empty store, and the store in use before is back at cleanup.
187	func TestFreshStartsEmptyAndRestores(t *testing.T) {
188		// A witness is the store in use when the subtests start. It holds a secret
189		// that a Fresh store must not show and that must reappear afterwards.
190		witness := fakekeyring.NewStore()
191		prev := credentials.SwapHostStoreForTest(witness)
192		t.Cleanup(func() { credentials.SwapHostStoreForTest(prev) })
193	
194		ks := credentials.NewKeyringStorage("ctx")
195		if err := ks.Save("https://h.example", "witness-token"); err != nil {
196			t.Fatalf("Save() on the witness = %v", err)
197		}
198	
199		var firstFresh *fakekeyring.Store
200	
201		t.Run("first test writes", func(t *testing.T) {
202			firstFresh = fakekeyring.Fresh(t)
203			if firstFresh == nil {
204				t.Fatal("Fresh() returned nil")
205			}
206			if n := len(firstFresh.Entries()); n != 0 {
207				t.Fatalf("Fresh() store has %d entries, want it empty", n)
208			}
209			if _, err := ks.Load("https://h.example"); !errors.Is(err, credentials.ErrNotFound) {
210				t.Fatalf("Load() under Fresh = %v, want ErrNotFound: the witness secret leaked into the fresh store", err)
211			}
212			// The code under test reaches the fake that Fresh returned.
213			if err := ks.Save("https://h.example", "first-token"); err != nil {
214				t.Fatalf("Save() under Fresh = %v", err)
215			}
216			if n := len(firstFresh.Entries()); n != 1 {
217				t.Errorf("the Fresh store holds %d entries after a Save, want 1: Fresh did not install it", n)
218			}
219		})
220	
221		t.Run("second test starts empty again", func(t *testing.T) {
222			second := fakekeyring.Fresh(t)
223			if second == firstFresh {
224				t.Error("Fresh() returned the same store twice, want a new one per test")
225			}
226			if n := len(second.Entries()); n != 0 {
227				t.Errorf("a second Fresh() store has %d entries, want it empty: the first test's secret survived", n)
228			}
229			if _, err := ks.Load("https://h.example"); !errors.Is(err, credentials.ErrNotFound) {
230				t.Errorf("Load() under the second Fresh = %v, want ErrNotFound", err)
231			}
232		})
233	
234		// Both subtests are over and their cleanups ran: the witness is back.
235		got, err := ks.Load("https://h.example")
236		if err != nil || got != "witness-token" {
237			t.Errorf("Load() after the subtests = %q, %v, want %q: Fresh did not restore the previous store", got, err, "witness-token")
238		}
239	}
