328	// TestSelectUnderFakeIgnoresTheSessionBus is AC 4: with the fake installed, the
329	// answer of Select does not depend on the session bus of the machine.
330	func TestSelectUnderFakeIgnoresTheSessionBus(t *testing.T) {
331		fakekeyring.Fresh(t)
332	
333		unsetBus := func(t *testing.T) {
334			t.Helper()
335			t.Setenv("DBUS_SESSION_BUS_ADDRESS", "") // registers the restore
336			if err := os.Unsetenv("DBUS_SESSION_BUS_ADDRESS"); err != nil {
337				t.Fatal(err)
338			}
339		}
340		deadBus := func(t *testing.T) {
341			t.Helper()
342			t.Setenv("DBUS_SESSION_BUS_ADDRESS", "unix:path=/nonexistent")
343		}
344	
345		type answer struct{ backend, detail string }
346		read := func(preference string) answer {
347			sel := credentials.Select("x", preference)
348			return answer{string(sel.Backend), sel.Detail}
349		}
350	
351		for _, preference := range []string{credentials.PreferenceAuto, credentials.PreferenceKeyring} {
352			t.Run(preference, func(t *testing.T) {
353				var without, with answer
354				t.Run("no bus variable", func(t *testing.T) {
355					unsetBus(t)
356					without = read(preference)
357				})
358				t.Run("bus path does not exist", func(t *testing.T) {
359					deadBus(t)
360					with = read(preference)
361				})
362	
363				if without != with {
364					t.Errorf("Select(%q) differs with the session bus: unset %+v, dead %+v", preference, without, with)
365				}
366				if without.backend != string(credentials.BackendKeyring) {
367					t.Errorf("Select(%q) backend = %q, want %q under the fake", preference, without.backend, credentials.BackendKeyring)
368				}
369			})
370		}
371	
372		// The storage Select returns works under a dead bus too.
373		deadBus(t)
374		sel := credentials.Select("x", credentials.PreferenceAuto)
375		if err := sel.Storage.Save("https://h.example", "tok"); err != nil {
376			t.Fatalf("Save() with a dead session bus = %v", err)
377		}
378		if got, err := sel.Storage.Load("https://h.example"); err != nil || got != "tok" {
379			t.Errorf("Load() with a dead session bus = %q, %v, want %q", got, err, "tok")
380		}
381	}
