425	// TestFreshIsSafeAgainstAConcurrentReader checks the seam itself: a Cmd that
426	// outlives its test reads the current store while Fresh's cleanup swaps it
427	// back. Run under -race.
428	func TestFreshIsSafeAgainstAConcurrentReader(t *testing.T) {
429		stop := make(chan struct{})
430		var wg sync.WaitGroup
431		wg.Add(1)
432		go func() {
433			defer wg.Done()
434			for {
435				select {
436				case <-stop:
437					return
438				default:
439					credentials.KeyringAvailable()
440				}
441			}
442		}()
443	
444		for i := 0; i < 50; i++ {
445			t.Run(fmt.Sprintf("round-%d", i), func(t *testing.T) {
446				fakekeyring.Fresh(t)
447			})
448		}
449		close(stop)
450		wg.Wait()
451	}
