383	// TestStoreIsSafeForConcurrentUse is meant to run under -race: Cmds of a Bubble
384	// Tea program read and write the store from their own goroutines.
385	func TestStoreIsSafeForConcurrentUse(t *testing.T) {
386		s := fakekeyring.NewStore()
387	
388		const workers, perWorker = 8, 200
389		var wg sync.WaitGroup
390		for w := 0; w < workers; w++ {
391			wg.Add(1)
392			go func() {
393				defer wg.Done()
394				account := fmt.Sprintf("acct-%d", w)
395				for i := 0; i < perWorker; i++ {
396					secret := fmt.Sprintf("secret-%d-%d", w, i)
397					if err := s.Set("svc", account, secret); err != nil {
398						t.Errorf("Set() = %v", err)
399						return
400					}
401					// Only this goroutine writes this account, so it reads back its own write.
402					if got, err := s.Get("svc", account); err != nil || got != secret {
403						t.Errorf("Get(%q) = %q, %v, want %q", account, got, err, secret)
404						return
405					}
406					// Reads of other accounts and the copy race with the writers.
407					_, _ = s.Get("svc", fmt.Sprintf("acct-%d", (w+1)%workers))
408					_ = s.Entries()
409					if i%50 == 49 {
410						if err := s.Delete("svc", "scratch"); err != nil {
411							t.Errorf("Delete() = %v", err)
412							return
413						}
414					}
415				}
416			}()
417		}
418		wg.Wait()
419	
420		if n := len(s.Entries()); n != workers {
421			t.Errorf("Entries() has %d entries after the run, want %d (one account per worker)", n, workers)
422		}
423	}
